"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { useAuthStore } from "@/store/auth-store";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { useToast } from "@/hooks/use-toast";
import { User, Phone, Lock, Eye, EyeOff, Save, X, Edit2, Package, MessageCircle, LogOut, CheckCircle2, AlertCircle, Shield } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";

function ProfileContent() {
  const { user, logout, updateUser } = useAuthStore();
  const { toast } = useToast();
  
  const [isEditing, setIsEditing] = useState(false);
  const [isEditingPassword, setIsEditingPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [showNewPassword, setShowNewPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  const [formData, setFormData] = useState({
    name: "",
    phone: "",
  });

  const [passwordData, setPasswordData] = useState({
    currentPassword: "",
    newPassword: "",
    confirmPassword: "",
  });

  const [errors, setErrors] = useState<{
    name?: string;
    phone?: string;
    currentPassword?: string;
    newPassword?: string;
    confirmPassword?: string;
  }>({});

  useEffect(() => {
    if (user) {
      setFormData({
        name: user.name || "",
        phone: (user as any)?.phone || "",
      });
    }
  }, [user]);

  const validateForm = () => {
    const newErrors: typeof errors = {};

    if (!formData.name.trim()) {
      newErrors.name = "نام الزامی است";
    } else if (formData.name.trim().length < 2) {
      newErrors.name = "نام باید حداقل 2 کاراکتر باشد";
    }

    if (!formData.phone.trim()) {
      newErrors.phone = "شماره تماس الزامی است";
    } else if (!/^09\d{9}$/.test(formData.phone.trim())) {
      newErrors.phone = "شماره تماس باید با 09 شروع شود و 11 رقم باشد";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const validatePassword = () => {
    const newErrors: typeof errors = {};

    if (!passwordData.currentPassword) {
      newErrors.currentPassword = "رمز عبور فعلی الزامی است";
    }

    if (!passwordData.newPassword) {
      newErrors.newPassword = "رمز عبور جدید الزامی است";
    } else if (passwordData.newPassword.length < 6) {
      newErrors.newPassword = "رمز عبور باید حداقل 6 کاراکتر باشد";
    }

    if (!passwordData.confirmPassword) {
      newErrors.confirmPassword = "تکرار رمز عبور الزامی است";
    } else if (passwordData.newPassword !== passwordData.confirmPassword) {
      newErrors.confirmPassword = "رمز عبور و تکرار آن یکسان نیستند";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSaveProfile = async () => {
    if (!validateForm()) {
      toast({
        title: "خطا",
        description: "لطفاً خطاهای فرم را برطرف کنید",
        variant: "destructive",
      });
      return;
    }

    if (!user?.id) {
      toast({
        title: "خطا",
        description: "کاربر یافت نشد",
        variant: "destructive",
      });
      return;
    }

    setIsLoading(true);
    try {
      const response = await fetch(`/api/users/${user.id}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
        },
        credentials: "include",
        body: JSON.stringify({
          name: formData.name.trim(),
          phone: formData.phone.trim(),
        }),
      });

      const result = await response.json();

      if (!response.ok || !result.success) {
        throw new Error(result.error || result.message || "خطا در به‌روزرسانی اطلاعات");
      }

      updateUser({
        name: formData.name.trim(),
        phone: formData.phone.trim(),
      } as any);

      setIsEditing(false);
      toast({
        title: "موفق",
        description: "اطلاعات با موفقیت به‌روزرسانی شد",
      });
    } catch (error: any) {
      toast({
        title: "خطا",
        description: error.message || "خطا در به‌روزرسانی اطلاعات",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleChangePassword = async () => {
    if (!validatePassword()) {
      toast({
        title: "خطا",
        description: "لطفاً خطاهای فرم را برطرف کنید",
        variant: "destructive",
      });
      return;
    }

    if (!user?.id) {
      toast({
        title: "خطا",
        description: "کاربر یافت نشد",
        variant: "destructive",
      });
      return;
    }

    setIsLoading(true);
    try {
      const loginResponse = await fetch("/api/auth/login", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        credentials: "include",
        body: JSON.stringify({
          phone: (user as any)?.phone,
          password: passwordData.currentPassword,
        }),
      });

      const loginResult = await loginResponse.json();

      if (!loginResponse.ok || !loginResult.success) {
        setErrors({ currentPassword: "رمز عبور فعلی اشتباه است" });
        throw new Error("رمز عبور فعلی اشتباه است");
      }

      const response = await fetch(`/api/users/${user.id}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
        },
        credentials: "include",
        body: JSON.stringify({
          password: passwordData.newPassword,
        }),
      });

      const result = await response.json();

      if (!response.ok || !result.success) {
        throw new Error(result.error || result.message || "خطا در تغییر رمز عبور");
      }

      setPasswordData({
        currentPassword: "",
        newPassword: "",
        confirmPassword: "",
      });
      setIsEditingPassword(false);
      setShowPassword(false);
      setShowNewPassword(false);
      setShowConfirmPassword(false);

      toast({
        title: "موفق",
        description: "رمز عبور با موفقیت تغییر کرد",
      });
    } catch (error: any) {
      if (error.message !== "رمز عبور فعلی اشتباه است") {
        toast({
          title: "خطا",
          description: error.message || "خطا در تغییر رمز عبور",
          variant: "destructive",
        });
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleCancel = () => {
    if (user) {
      setFormData({
        name: user.name || "",
        phone: (user as any)?.phone || "",
      });
    }
    setErrors({});
    setIsEditing(false);
  };

  const handleCancelPassword = () => {
    setPasswordData({
      currentPassword: "",
      newPassword: "",
      confirmPassword: "",
    });
    setErrors({});
    setIsEditingPassword(false);
    setShowPassword(false);
    setShowNewPassword(false);
    setShowConfirmPassword(false);
  };

  if (!user) {
    return (
      <div className="min-h-screen flex items-center justify-center px-4">
        <Card className="w-full max-w-md">
          <CardContent className="p-8 text-center">
            <p className="text-muted-foreground mb-4">لطفاً ابتدا وارد حساب کاربری خود شوید</p>
            <Button asChild>
              <Link href="/auth">ورود / ثبت‌نام</Link>
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-b from-background via-background to-muted/20 py-6 sm:py-8 px-4">
      <div className="max-w-4xl mx-auto space-y-6">
        {/* Header Section */}
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-center space-y-2"
        >
          <h1 className="text-3xl sm:text-4xl font-bold bg-gradient-to-r from-primary to-primary/60 bg-clip-text text-transparent">
            پروفایل کاربری
          </h1>
          <p className="text-muted-foreground">مدیریت اطلاعات و تنظیمات حساب کاربری</p>
        </motion.div>

        {/* Main Content Grid */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Left Column - Profile Info */}
          <div className="lg:col-span-2 space-y-6">
            {/* Profile Information Card */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.1 }}
            >
              <Card className="glass-morphism-light border-border/30 overflow-hidden">
                <CardHeader className="bg-gradient-to-r from-primary/5 to-primary/10 border-b border-border/30">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <div className="p-2 bg-primary/10 rounded-lg">
                        <User className="h-5 w-5 text-primary" />
                      </div>
                      <CardTitle className="text-xl">اطلاعات شخصی</CardTitle>
                    </div>
                    {!isEditing && (
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => setIsEditing(true)}
                        className="flex items-center gap-2"
                      >
                        <Edit2 className="h-4 w-4" />
                        ویرایش
                      </Button>
                    )}
                  </div>
                </CardHeader>
                <CardContent className="p-6">
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                    {/* Name Field */}
                    <div className="space-y-2">
                      <Label htmlFor="name" className="text-sm font-medium flex items-center gap-2">
                        <User className="h-3.5 w-3.5" />
                        نام
                      </Label>
                      {isEditing ? (
                        <div className="space-y-1">
                          <Input
                            id="name"
                            value={formData.name}
                            onChange={(e) => {
                              setFormData({ ...formData, name: e.target.value });
                              if (errors.name) setErrors({ ...errors, name: undefined });
                            }}
                            placeholder="نام خود را وارد کنید"
                            className={`h-11 ${errors.name ? "border-destructive focus-visible:ring-destructive" : ""}`}
                          />
                          {errors.name && (
                            <p className="text-xs text-destructive flex items-center gap-1">
                              <AlertCircle className="h-3 w-3" />
                              {errors.name}
                            </p>
                          )}
                        </div>
                      ) : (
                        <div className="h-11 px-4 bg-muted/50 rounded-md flex items-center text-sm font-medium border border-transparent">
                          {user.name || "-"}
                        </div>
                      )}
                    </div>

                    {/* Phone Field */}
                    <div className="space-y-2">
                      <Label htmlFor="phone" className="text-sm font-medium flex items-center gap-2">
                        <Phone className="h-3.5 w-3.5" />
                        شماره تماس
                      </Label>
                      {isEditing ? (
                        <div className="space-y-1">
                          <Input
                            id="phone"
                            type="tel"
                            value={formData.phone}
                            onChange={(e) => {
                              const value = e.target.value.replace(/\D/g, "");
                              setFormData({ ...formData, phone: value });
                              if (errors.phone) setErrors({ ...errors, phone: undefined });
                            }}
                            placeholder="09123456789"
                            maxLength={11}
                            className={`h-11 ${errors.phone ? "border-destructive focus-visible:ring-destructive" : ""}`}
                          />
                          {errors.phone && (
                            <p className="text-xs text-destructive flex items-center gap-1">
                              <AlertCircle className="h-3 w-3" />
                              {errors.phone}
                            </p>
                          )}
                        </div>
                      ) : (
                        <div className="h-11 px-4 bg-muted/50 rounded-md flex items-center text-sm font-medium border border-transparent">
                          {(user as any)?.phone || "-"}
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Action Buttons */}
                  {isEditing && (
                    <motion.div
                      initial={{ opacity: 0, height: 0 }}
                      animate={{ opacity: 1, height: "auto" }}
                      className="flex gap-3 mt-6 pt-6 border-t border-border/30"
                    >
                      <Button
                        onClick={handleSaveProfile}
                        disabled={isLoading}
                        className="flex-1 flex items-center gap-2"
                      >
                        <Save className="h-4 w-4" />
                        {isLoading ? "در حال ذخیره..." : "ذخیره تغییرات"}
                      </Button>
                      <Button
                        variant="outline"
                        onClick={handleCancel}
                        disabled={isLoading}
                        className="flex items-center gap-2"
                      >
                        <X className="h-4 w-4" />
                        لغو
                      </Button>
                    </motion.div>
                  )}
                </CardContent>
              </Card>
            </motion.div>

            {/* Password Card */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.2 }}
            >
              <Card className="glass-morphism-light border-border/30 overflow-hidden">
                <CardHeader className="bg-gradient-to-r from-primary/5 to-primary/10 border-b border-border/30">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <div className="p-2 bg-primary/10 rounded-lg">
                        <Shield className="h-5 w-5 text-primary" />
                      </div>
                      <CardTitle className="text-xl">امنیت و رمز عبور</CardTitle>
                    </div>
                    {!isEditingPassword && (
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => setIsEditingPassword(true)}
                        className="flex items-center gap-2"
                      >
                        <Lock className="h-4 w-4" />
                        تغییر رمز
                      </Button>
                    )}
                  </div>
                </CardHeader>
                <CardContent className="p-6">
                  <AnimatePresence>
                    {isEditingPassword ? (
                      <motion.div
                        initial={{ opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: "auto" }}
                        exit={{ opacity: 0, height: 0 }}
                        className="space-y-4"
                      >
                        {/* Current Password */}
                        <div className="space-y-2">
                          <Label htmlFor="currentPassword" className="text-sm font-medium">
                            رمز عبور فعلی
                          </Label>
                          <div className="relative">
                            <Input
                              id="currentPassword"
                              type={showPassword ? "text" : "password"}
                              value={passwordData.currentPassword}
                              onChange={(e) => {
                                setPasswordData({ ...passwordData, currentPassword: e.target.value });
                                if (errors.currentPassword) setErrors({ ...errors, currentPassword: undefined });
                              }}
                              placeholder="رمز عبور فعلی را وارد کنید"
                              className={`h-11 pr-10 ${errors.currentPassword ? "border-destructive focus-visible:ring-destructive" : ""}`}
                            />
                            <Button
                              type="button"
                              variant="ghost"
                              size="sm"
                              className="absolute left-0 top-0 h-full px-3 hover:bg-transparent"
                              onClick={() => setShowPassword(!showPassword)}
                            >
                              {showPassword ? (
                                <EyeOff className="h-4 w-4 text-muted-foreground" />
                              ) : (
                                <Eye className="h-4 w-4 text-muted-foreground" />
                              )}
                            </Button>
                          </div>
                          {errors.currentPassword && (
                            <p className="text-xs text-destructive flex items-center gap-1">
                              <AlertCircle className="h-3 w-3" />
                              {errors.currentPassword}
                            </p>
                          )}
                        </div>

                        {/* New Password */}
                        <div className="space-y-2">
                          <Label htmlFor="newPassword" className="text-sm font-medium">
                            رمز عبور جدید
                          </Label>
                          <div className="relative">
                            <Input
                              id="newPassword"
                              type={showNewPassword ? "text" : "password"}
                              value={passwordData.newPassword}
                              onChange={(e) => {
                                setPasswordData({ ...passwordData, newPassword: e.target.value });
                                if (errors.newPassword) setErrors({ ...errors, newPassword: undefined });
                              }}
                              placeholder="رمز عبور جدید را وارد کنید (حداقل 6 کاراکتر)"
                              className={`h-11 pr-10 ${errors.newPassword ? "border-destructive focus-visible:ring-destructive" : ""}`}
                              minLength={6}
                            />
                            <Button
                              type="button"
                              variant="ghost"
                              size="sm"
                              className="absolute left-0 top-0 h-full px-3 hover:bg-transparent"
                              onClick={() => setShowNewPassword(!showNewPassword)}
                            >
                              {showNewPassword ? (
                                <EyeOff className="h-4 w-4 text-muted-foreground" />
                              ) : (
                                <Eye className="h-4 w-4 text-muted-foreground" />
                              )}
                            </Button>
                          </div>
                          {errors.newPassword && (
                            <p className="text-xs text-destructive flex items-center gap-1">
                              <AlertCircle className="h-3 w-3" />
                              {errors.newPassword}
                            </p>
                          )}
                          {passwordData.newPassword && !errors.newPassword && passwordData.newPassword.length >= 6 && (
                            <p className="text-xs text-green-600 dark:text-green-400 flex items-center gap-1">
                              <CheckCircle2 className="h-3 w-3" />
                              رمز عبور معتبر است
                            </p>
                          )}
                        </div>

                        {/* Confirm Password */}
                        <div className="space-y-2">
                          <Label htmlFor="confirmPassword" className="text-sm font-medium">
                            تکرار رمز عبور جدید
                          </Label>
                          <div className="relative">
                            <Input
                              id="confirmPassword"
                              type={showConfirmPassword ? "text" : "password"}
                              value={passwordData.confirmPassword}
                              onChange={(e) => {
                                setPasswordData({ ...passwordData, confirmPassword: e.target.value });
                                if (errors.confirmPassword) setErrors({ ...errors, confirmPassword: undefined });
                              }}
                              placeholder="رمز عبور جدید را دوباره وارد کنید"
                              className={`h-11 pr-10 ${errors.confirmPassword ? "border-destructive focus-visible:ring-destructive" : ""}`}
                            />
                            <Button
                              type="button"
                              variant="ghost"
                              size="sm"
                              className="absolute left-0 top-0 h-full px-3 hover:bg-transparent"
                              onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                            >
                              {showConfirmPassword ? (
                                <EyeOff className="h-4 w-4 text-muted-foreground" />
                              ) : (
                                <Eye className="h-4 w-4 text-muted-foreground" />
                              )}
                            </Button>
                          </div>
                          {errors.confirmPassword && (
                            <p className="text-xs text-destructive flex items-center gap-1">
                              <AlertCircle className="h-3 w-3" />
                              {errors.confirmPassword}
                            </p>
                          )}
                          {passwordData.confirmPassword &&
                            !errors.confirmPassword &&
                            passwordData.newPassword === passwordData.confirmPassword &&
                            passwordData.confirmPassword.length >= 6 && (
                              <p className="text-xs text-green-600 dark:text-green-400 flex items-center gap-1">
                                <CheckCircle2 className="h-3 w-3" />
                                رمز عبورها یکسان هستند
                              </p>
                            )}
                        </div>

                        {/* Action Buttons */}
                        <div className="flex gap-3 pt-2">
                          <Button
                            onClick={handleChangePassword}
                            disabled={isLoading}
                            className="flex-1 flex items-center gap-2"
                          >
                            <Save className="h-4 w-4" />
                            {isLoading ? "در حال تغییر..." : "تغییر رمز عبور"}
                          </Button>
                          <Button
                            variant="outline"
                            onClick={handleCancelPassword}
                            disabled={isLoading}
                            className="flex items-center gap-2"
                          >
                            <X className="h-4 w-4" />
                            لغو
                          </Button>
                        </div>
                      </motion.div>
                    ) : (
                      <div className="text-sm text-muted-foreground py-4">
                        برای تغییر رمز عبور، روی دکمه "تغییر رمز" کلیک کنید
                      </div>
                    )}
                  </AnimatePresence>
                </CardContent>
              </Card>
            </motion.div>
          </div>

          {/* Right Column - Quick Actions */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.3 }}
            className="space-y-4"
          >
            <Card className="glass-morphism-light border-border/30">
              <CardHeader>
                <CardTitle className="text-lg">دسترسی سریع</CardTitle>
              </CardHeader>
              <CardContent className="space-y-3">
                <Button asChild variant="outline" className="w-full justify-start gap-3 h-auto py-3">
                  <Link href="/orders">
                    <Package className="h-5 w-5" />
                    <div className="flex flex-col items-start">
                      <span className="font-medium">سفارش‌های من</span>
                      <span className="text-xs text-muted-foreground">مشاهده سفارش‌ها</span>
                    </div>
                  </Link>
                </Button>
                <Button asChild variant="outline" className="w-full justify-start gap-3 h-auto py-3">
                  <Link href="/chat">
                    <MessageCircle className="h-5 w-5" />
                    <div className="flex flex-col items-start">
                      <span className="font-medium">پشتیبانی</span>
                      <span className="text-xs text-muted-foreground">چت با پشتیبانی</span>
                    </div>
                  </Link>
                </Button>
                <Button
                  variant="destructive"
                  onClick={() => logout()}
                  className="w-full justify-start gap-3 h-auto py-3"
                >
                  <LogOut className="h-5 w-5" />
                  <div className="flex flex-col items-start">
                    <span className="font-medium">خروج از حساب</span>
                    <span className="text-xs opacity-80">خروج از حساب کاربری</span>
                  </div>
                </Button>
              </CardContent>
            </Card>
          </motion.div>
        </div>
      </div>
    </div>
  );
}

export default function ProfilePage() {
  return <ProfileContent />;
}
